const STRIPE_VERSION = '2026-08-26.dahlia';
const wrongVersion = ev => ev.payload.api_version !== STRIPE_VERSION &&
  `PERMANENT: event is in Stripe API version ${ev.payload.api_version}; pin the webhook endpoint to ${STRIPE_VERSION}`;

// refunds already in Xero, failed or cancelled ones and foreign currencies are settled here. the rest need
// their invoice: a refund points at a PaymentIntent, Stripe's invoice_payments maps that to the invoice
const { settings: s, links } = $('Load context').first().json.ctx;
const outcomes = [], refunds = [];
for (const { json: ev } of $('Events').all()) {
  const re = ev.payload.data.object;
  const currency = String(re.currency).toUpperCase();
  const settle = outcome => outcomes.push({ event_id: ev.id, ...outcome });
  if (links[re.id]?.refund) settle({ note: 'already in Xero' });
  else if (wrongVersion(ev)) settle({ error: wrongVersion(ev) });
  else if (!['succeeded', 'pending'].includes(re.status)) settle({ note: `refund is ${re.status}, nothing to post` });
  else if (currency !== s.xero_currency) settle({ error: `PERMANENT: currency ${currency} is not the Xero organisation's ${s.xero_currency}` });
  else if (!re.payment_intent) settle({ note: 'refund has no PaymentIntent, so no invoice to credit' });
  else refunds.push({ event_id: ev.id, refund: re });
}
return [{ json: { plan: { settings: s, links, outcomes, refunds } } }];

const { plan } = $('Plan').first().json;
const lookups = plan.refunds.map(({ refund }) => ({ json: {
  service: 'stripe', method: 'GET',
  url: `${plan.settings.stripe_api_base}/v1/invoice_payments?payment%5Btype%5D=payment_intent&payment%5Bpayment_intent%5D=${refund.payment_intent}&limit=1`,
} }));
return lookups.length ? lookups : [{ json: { skip: true } }];

// a refund is credited only once its invoice is in Xero. until then it waits without spending attempts (up to
// 2 days, see finish_event). so a refund that came before its invoice.paid, or whose invoice.paid webhook got lost
// and comes back with the nightly reconcile, still lands after it
const { plan } = $('Plan').first().json;
const invoiceLinks = $('Invoice links').first().json.ctx.links;
const answers = $('Stripe: find invoices').all();
const ready = [], outcomes = [];
plan.refunds.forEach(({ event_id, refund }, i) => {
  const invoice = answers[i]?.json.data?.[0]?.invoice;
  const contact = plan.links[refund.customer]?.contact;
  if (!invoice) outcomes.push({ event_id, note: 'not an invoice payment, nothing to credit' });
  else if (!invoiceLinks[invoice]?.invoice || !contact) outcomes.push({ event_id, error: `WAITING: invoice ${invoice} is not in Xero yet` });
  else ready.push({ event_id, refund, invoice, contact });
});
const where = ready.map(r => `Reference=="${r.refund.id}"`).join(' OR ');
return [{ json: {
  ...(ready.length ? { service: 'xero', method: 'GET', url: `${plan.settings.xero_api_base}/CreditNotes?where=${encodeURIComponent(where)}` } : { skip: true }),
  ready, outcomes,
} }];

const ZERO_DECIMAL = ['BIF', 'CLP', 'DJF', 'GNF', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'];
const THREE_DECIMAL = ['BHD', 'JOD', 'KWD', 'OMR', 'TND'];
const unitOf = currency => ZERO_DECIMAL.includes(currency) ? 1 : THREE_DECIMAL.includes(currency) ? 1000 : 100;
const day = ts => new Date(ts * 1000).toISOString().slice(0, 10);
// credit notes found or created, by Reference (the Stripe refund id)
const creditNotes = () => {
  const byRef = {};
  for (const node of ['Xero: find credit notes', 'Xero: create credit notes']) {
    if (!$(node).isExecuted) continue;
    for (const c of $(node).first().json.CreditNotes ?? []) if (c.StatusAttributeString !== 'ERROR') byRef[c.Reference] = c;
  }
  return byRef;
};

const { plan } = $('Plan').first().json;
const { ready } = $('Credit notes to look up').first().json;
const s = plan.settings, unit = unitOf(s.xero_currency), found = creditNotes();
const create = ready.filter(r => !found[r.refund.id]).map(({ refund, invoice, contact }) => ({
  Type: 'ACCRECCREDIT', Contact: { ContactID: contact }, Reference: refund.id, Status: 'AUTHORISED',
  CurrencyCode: s.xero_currency, Date: day(refund.created), LineAmountTypes: 'NoTax',
  LineItems: [{ Description: `Refund ${refund.id} of Stripe invoice ${invoice}`, Quantity: 1, UnitAmount: refund.amount / unit, AccountCode: s.xero_sales_account }],
}));
return [{ json: create.length
  ? { service: 'xero', method: 'PUT', url: `${s.xero_api_base}/CreditNotes?summarizeErrors=false`, body: { CreditNotes: create } }
  : { skip: true } }];

const ZERO_DECIMAL = ['BIF', 'CLP', 'DJF', 'GNF', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'];
const THREE_DECIMAL = ['BHD', 'JOD', 'KWD', 'OMR', 'TND'];
const unitOf = currency => ZERO_DECIMAL.includes(currency) ? 1 : THREE_DECIMAL.includes(currency) ? 1000 : 100;
const day = ts => new Date(ts * 1000).toISOString().slice(0, 10);
// credit notes found or created, by Reference (the Stripe refund id)
const creditNotes = () => {
  const byRef = {};
  for (const node of ['Xero: find credit notes', 'Xero: create credit notes']) {
    if (!$(node).isExecuted) continue;
    for (const c of $(node).first().json.CreditNotes ?? []) if (c.StatusAttributeString !== 'ERROR') byRef[c.Reference] = c;
  }
  return byRef;
};

// pay each credit note out of the bank account, that's the money going back to the customer
const { plan } = $('Plan').first().json;
const { ready } = $('Credit notes to look up').first().json;
const s = plan.settings, unit = unitOf(s.xero_currency), notes = creditNotes();
const pay = [];
for (const { refund } of ready) {
  const cn = notes[refund.id];
  if (cn && cn.Status === 'AUTHORISED' && Math.abs(cn.RemainingCredit - refund.amount / unit) < 0.0005) {
    pay.push({ CreditNote: { CreditNoteID: cn.CreditNoteID }, Account: { Code: s.xero_bank_account },
               Amount: refund.amount / unit, Date: day(refund.created), Reference: refund.id });
  }
}
return [{ json: pay.length
  ? { service: 'xero', method: 'PUT', url: `${s.xero_api_base}/Payments?summarizeErrors=false`, body: { Payments: pay } }
  : { skip: true } }];

const ZERO_DECIMAL = ['BIF', 'CLP', 'DJF', 'GNF', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'];
const THREE_DECIMAL = ['BHD', 'JOD', 'KWD', 'OMR', 'TND'];
const unitOf = currency => ZERO_DECIMAL.includes(currency) ? 1 : THREE_DECIMAL.includes(currency) ? 1000 : 100;
const day = ts => new Date(ts * 1000).toISOString().slice(0, 10);
const problems = el => (el.ValidationErrors ?? []).map(e => e.Message).join('; ') || 'rejected by Xero';
const ok = el => el.StatusAttributeString !== 'ERROR';
// credit notes found or created, by Reference (the Stripe refund id)
const creditNotes = () => {
  const byRef = {};
  for (const node of ['Xero: find credit notes', 'Xero: create credit notes']) {
    if (!$(node).isExecuted) continue;
    for (const c of $(node).first().json.CreditNotes ?? []) if (c.StatusAttributeString !== 'ERROR') byRef[c.Reference] = c;
  }
  return byRef;
};

const { plan } = $('Plan').first().json;
const lookedUp = $('Credit notes to look up').first().json;
const unit = unitOf(plan.settings.xero_currency), notes = creditNotes();
const failedNote = {}, failedRefund = {}, refunded = {};
for (const c of $('Xero: create credit notes').first().json.CreditNotes ?? []) if (!ok(c)) failedNote[c.Reference] = problems(c);
for (const p of $('Xero: record refunds').first().json.Payments ?? []) {
  if (ok(p)) refunded[p.CreditNote.CreditNoteID] = p; else failedRefund[p.CreditNote.CreditNoteID] = problems(p);
}
const results = [...plan.outcomes, ...lookedUp.outcomes], links = [];
for (const { event_id, refund } of lookedUp.ready) {
  const cn = notes[refund.id];
  let error = null;
  if (!cn) error = `Xero credit note: ${failedNote[refund.id] ?? 'not found and not created'}`;
  else if (refunded[cn.CreditNoteID] || cn.RemainingCredit === 0) {
    links.push({ stripe_id: refund.id, kind: 'credit_note', xero_id: cn.CreditNoteID, amount: cn.Total });
    const paymentId = refunded[cn.CreditNoteID]?.PaymentID ?? cn.Payments?.[0]?.PaymentID;
    if (paymentId) links.push({ stripe_id: refund.id, kind: 'refund', xero_id: paymentId, amount: refund.amount / unit });
  } else if (failedRefund[cn.CreditNoteID]) error = `Xero refund: ${failedRefund[cn.CreditNoteID]}`;
  else error = `PERMANENT: Xero credit note ${cn.CreditNoteNumber} is ${cn.Status} with ${cn.RemainingCredit} left, Stripe refunded ${refund.amount / unit}`;
  results.push({ event_id, error });
}
return [{ json: { links, results } }];
